REQUIRED = ["DATABASE_URL", "API_KEY", "LOG_LEVEL"]


def missing_variables(required, environ):
    return sorted(
        name
        for name in set(required)
        if not isinstance(environ.get(name), str) or not environ[name].strip()
    )


def readiness_line(required, environ):
    missing = missing_variables(required, environ)
    if missing:
        return "missing: " + ", ".join(missing)
    return "ready"


def main():
    sample = {
        "DATABASE_URL": "postgres://example",
        "API_KEY": "",
        "LOG_LEVEL": "info",
    }
    print(readiness_line(REQUIRED, sample))


if __name__ == "__main__":
    main()
